import { AccessTimeRounded, GroupsRounded, UpdateRounded, WarningAmberRounded } from "@mui/icons-material";
import { Box, Card, CardContent, Typography } from "@mui/material";
import { formatDateTime } from "../utils";

function SyncMetric({ icon, label, value, tone = "primary" }) {
  return (
    <Card className={`roster-sync-metric is-${tone}`}>
      <CardContent>
        <Box className="roster-sync-metric-icon">{icon}</Box>
        <Box>
          <Typography className="roster-sync-metric-label">{label}</Typography>
          <Typography className="roster-sync-metric-value">{value}</Typography>
        </Box>
      </CardContent>
    </Card>
  );
}

function SyncSummaryCard({ summary }) {
  if (!summary || !summary.success) return null;

  const lastSynced = summary.syncedAt ? formatDateTime(summary.syncedAt) : "â€”";

  return (
    <Box className="roster-sync-metrics">
      <SyncMetric icon={<GroupsRounded />} label="Staff Synced" value={summary.staffSynced} />
      <SyncMetric icon={<AccessTimeRounded />} label="Total Hours" value={summary.totalHours} />
      <SyncMetric icon={<WarningAmberRounded />} label="Unmatched" value={summary.unmatchedCount} tone={summary.unmatchedCount ? "warning" : "success"} />
      <SyncMetric icon={<UpdateRounded />} label="Last Synced" value={lastSynced} />
    </Box>
  );
}

export default SyncSummaryCard;
import { Alert, Chip, Table, TableBody, TableCell, TableContainer, TableHead, TableRow } from "@mui/material";
import { formatDateTime } from "../utils";

function SyncHistoryList({ history }) {
  if (!history?.length) return <Alert severity="info">No sync history yet for this pay period.</Alert>;

  return (
    <TableContainer className="roster-sync-history-table">
      <Table aria-label="Sync history">
        <TableHead>
          <TableRow>
            <TableCell>Status</TableCell>
            <TableCell>Triggered By</TableCell>
            <TableCell>Detail</TableCell>
            <TableCell>Time</TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {history.map((entry, index) => {
            const failed = entry.action === "roster_sync_failed";
            const actor = entry.actor === "scheduler" ? "Automatic" : "Manual (Import Now)";
            return (
              <TableRow key={`${entry.createdAt}-${index}`}>
                <TableCell><Chip size="small" color={failed ? "error" : "success"} label={failed ? "Failed" : "Synced"} /></TableCell>
                <TableCell>{actor}</TableCell>
                <TableCell>{failed ? entry.detail?.reason : `${entry.detail?.staffSynced ?? 0} staff, ${entry.detail?.totalHours ?? 0}h`}</TableCell>
                <TableCell>{formatDateTime(entry.createdAt)}</TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </TableContainer>
  );
}

export default SyncHistoryList;
